window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["x.ai"]={html:"<div class=\"own-x-ai\">\n  <header class=\"xa-nav\">\n    <a class=\"xa-brand\" href=\"#xa-top\">NORTHWIND</a>\n    <nav class=\"xa-nav-links\" aria-label=\"Primary\">\n      <a href=\"#xa-products\">Products</a>\n      <a href=\"#xa-metrics\">Scale</a>\n      <a href=\"#xa-pricing\">Pricing</a>\n    </nav>\n    <div class=\"xa-nav-actions\">\n      <a class=\"xa-pill xa-pill-sm\" href=\"#xa-products\">Read</a>\n      <a class=\"xa-pill xa-pill-fill xa-pill-sm\" href=\"#xa-cta\">Sign up</a>\n    </div>\n  </header>\n\n  <main>\n    <section class=\"xa-hero\" id=\"xa-top\" aria-labelledby=\"xaHeroH\">\n      <p class=\"xa-eyebrow\">NORTHWIND / OPERATIONS ANALYTICS</p>\n      <h1 class=\"xa-hero-title\" id=\"xaHeroH\">One board for the entire operation.</h1>\n      <p class=\"xa-hero-lead\">Modelled throughput, governed regions, shift-aware alerts. Built for the teams that run the floor, not the ones that report on it.</p>\n      <div class=\"xa-hero-cta\">\n        <a class=\"xa-pill\" href=\"#xa-products\">Explore the platform</a>\n        <a class=\"xa-pill xa-pill-fill\" href=\"#xa-cta\">Try Northwind</a>\n      </div>\n    </section>\n\n    <section class=\"xa-metrics\" id=\"xa-metrics\" aria-labelledby=\"xaMetricsH\">\n      <h2 class=\"xa-sr\" id=\"xaMetricsH\">At a glance</h2>\n      <div class=\"xa-metric-row\">\n        <div class=\"xa-metric\"><span class=\"xa-metric-num\" data-xa-count=\"18420\">18,420</span><span class=\"xa-metric-cap\">UNIT / HR PEAK</span></div>\n        <div class=\"xa-metric\"><span class=\"xa-metric-num\" data-xa-count=\"97\">97</span><span class=\"xa-metric-cap\">% ON-TIME</span></div>\n        <div class=\"xa-metric\"><span class=\"xa-metric-num\" data-xa-count=\"5\">5</span><span class=\"xa-metric-cap\">REGIONS LIVE</span></div>\n        <div class=\"xa-metric\"><span class=\"xa-metric-num\" data-xa-count=\"120\">120</span><span class=\"xa-metric-cap\">MS LATENCY</span></div>\n      </div>\n    </section>\n\n    <section class=\"xa-products\" id=\"xa-products\" aria-labelledby=\"xaProdH\">\n      <p class=\"xa-eyebrow\">WHAT WE BUILD</p>\n      <h2 class=\"xa-sec-title\" id=\"xaProdH\">Engineered for the floor.</h2>\n      <div class=\"xa-product-grid\">\n        <article class=\"xa-card\">\n          <span class=\"xa-card-ico\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 48 48\"><path d=\"M6 40V20M14 40V8M22 40V26M30 40V14M38 40V24\" stroke=\"#ff7a17\"/></svg>\n          </span>\n          <p class=\"xa-card-tag\">THROUGHPUT</p>\n          <h3 class=\"xa-card-title\">A live, governed metric</h3>\n          <p class=\"xa-card-body\">Every number resolves to a source model. No reconciliation, no re-keyed totals.</p>\n          <a class=\"xa-pill xa-pill-sm\" href=\"#\">Read</a>\n        </article>\n        <article class=\"xa-card\">\n          <span class=\"xa-card-ico\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 48 48\"><circle cx=\"24\" cy=\"24\" r=\"16\" fill=\"none\" stroke=\"#7c3aed\" stroke-width=\"2\"/><path d=\"M24 12v12l9 5\" fill=\"none\" stroke=\"#c4b5fd\" stroke-width=\"2\"/></svg>\n          </span>\n          <p class=\"xa-card-tag\">ALERTS</p>\n          <h3 class=\"xa-card-title\">Shift-aware thresholds</h3>\n          <p class=\"xa-card-body\">The right supervisor is paged at the right hour — rules respect the roster.</p>\n          <a class=\"xa-pill xa-pill-sm\" href=\"#\">Read</a>\n        </article>\n        <article class=\"xa-card\">\n          <span class=\"xa-card-ico\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 48 48\"><path d=\"M8 16h32M8 24h20M8 32h26\" stroke=\"#a0c3ec\" stroke-width=\"2\"/></svg>\n          </span>\n          <p class=\"xa-card-tag\">REGIONS</p>\n          <h3 class=\"xa-card-title\">Roll-ups you can trace</h3>\n          <p class=\"xa-card-body\">Five regions, one true total. Every roll-up points back to its stream.</p>\n          <a class=\"xa-pill xa-pill-sm\" href=\"#\">Read</a>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"xa-console\" aria-labelledby=\"xaConsoleH\">\n      <div class=\"xa-console-head\">\n        <p class=\"xa-eyebrow\">LIVE CONSOLE</p>\n        <h2 class=\"xa-sec-title\" id=\"xaConsoleH\">The operation, streamed.</h2>\n      </div>\n      <div class=\"xa-term\" role=\"img\" aria-label=\"Northwind live throughput console, mock interface\">\n        <div class=\"xa-term-bar\">\n          <span class=\"xa-term-dot\"></span><span class=\"xa-term-dot\"></span><span class=\"xa-term-dot\"></span>\n          <span class=\"xa-term-title\">northwind --live --region northwest</span>\n        </div>\n        <pre class=\"xa-term-body\" aria-hidden=\"true\"><span class=\"xa-c-dim\">14:02:11</span> stream connected        <span class=\"xa-c-ok\">ok</span>\n<span class=\"xa-c-dim\">14:02:11</span> model throughput_v4       <span class=\"xa-c-ok\">ok</span>\n<span class=\"xa-c-dim\">14:02:12</span> region northwest          <span class=\"xa-c-hot\">18420</span> units/hr\n<span class=\"xa-c-dim\">14:02:12</span> region eastern            <span class=\"xa-c-hot\">15870</span> units/hr\n<span class=\"xa-c-dim\">14:02:13</span> region gulf               <span class=\"xa-c-warn\">12240</span> units/hr\n<span class=\"xa-c-dim\">14:02:13</span> on-time rate                <span class=\"xa-c-ok\">0.97</span>\n<span class=\"xa-c-dim\">14:02:14</span> incidents open                   <span class=\"xa-c-ok\">3</span>\n<span class=\"xa-c-dim\">14:02:14</span> <span class=\"xa-c-cursor\">_</span></pre>\n      </div>\n    </section>\n\n    <section class=\"xa-pricing\" id=\"xa-pricing\" aria-labelledby=\"xaPriceH\">\n      <p class=\"xa-eyebrow\">ACCESS</p>\n      <h2 class=\"xa-sec-title\" id=\"xaPriceH\">Choose your access.</h2>\n      <div class=\"xa-price-grid\">\n        <article class=\"xa-price-card\">\n          <h3>Starter</h3>\n          <p class=\"xa-price\"><span>$0</span> / month</p>\n          <ul class=\"xa-feats\"><li>1 live board</li><li>3 streams</li><li>7-day history</li></ul>\n          <a class=\"xa-pill xa-pill-block\" href=\"#\">Get started</a>\n        </article>\n        <article class=\"xa-price-card xa-price-feat\">\n          <p class=\"xa-card-tag\">MOST POPULAR</p>\n          <h3>Growth</h3>\n          <p class=\"xa-price\"><span>$240</span> / month</p>\n          <ul class=\"xa-feats\"><li>Unlimited boards</li><li>40 streams</li><li>Shift-aware alerts</li><li>Versioned history</li></ul>\n          <a class=\"xa-pill xa-pill-fill xa-pill-block\" href=\"#\">Start free trial</a>\n        </article>\n        <article class=\"xa-price-card\">\n          <h3>Scale</h3>\n          <p class=\"xa-price\"><span>Contact us</span></p>\n          <ul class=\"xa-feats\"><li>Everything in Growth</li><li>SSO and audit log</li><li>Dedicated modeler</li></ul>\n          <a class=\"xa-pill xa-pill-block\" href=\"#\">Talk to us</a>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"xa-cta\" id=\"xa-cta\" aria-labelledby=\"xaCtaH\">\n      <p class=\"xa-eyebrow\">GET STARTED</p>\n      <h2 class=\"xa-cta-title\" id=\"xaCtaH\">Run the floor on one board.</h2>\n      <div class=\"xa-hero-cta\">\n        <a class=\"xa-pill xa-pill-fill\" href=\"#\">Sign up now</a>\n        <a class=\"xa-pill\" href=\"#\">Book a demo</a>\n      </div>\n    </section>\n  </main>\n\n  <footer class=\"xa-footer\">\n    <div class=\"xa-foot-grid\">\n      <div class=\"xa-foot-brand\">\n        <span class=\"xa-brand\">NORTHWIND</span>\n        <p>Operations analytics for the people running the floor.</p>\n      </div>\n      <nav class=\"xa-foot-col\" aria-label=\"Product\">\n        <h4>PRODUCT</h4>\n        <a href=\"#xa-products\">Platform</a>\n        <a href=\"#xa-metrics\">Scale</a>\n        <a href=\"#xa-pricing\">Pricing</a>\n      </nav>\n      <nav class=\"xa-foot-col\" aria-label=\"Company\">\n        <h4>COMPANY</h4>\n        <a href=\"#\">About</a>\n        <a href=\"#\">Careers</a>\n        <a href=\"#\">Contact</a>\n      </nav>\n      <nav class=\"xa-foot-col\" aria-label=\"Resources\">\n        <h4>RESOURCES</h4>\n        <a href=\"#\">Docs</a>\n        <a href=\"#\">API</a>\n        <a href=\"#\">Status</a>\n      </nav>\n    </div>\n    <div class=\"xa-foot-base\">\n      <span>Sample data — showcase only</span>\n      <span>&copy; 2026 Northwind</span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ X.AI — own layout for showcase.html ═══════════════════════════════════\n   Ported from the xAI design language in DESIGN.md: near-black #0a0a0a canvas,\n   white outline pills as the entire interactive vocabulary, Universal Sans\n   weight 400 with aggressive negative tracking (Inter substitute) paired with\n   GeistMono uppercase tracked eyebrows, 8px charcoal cards with hairline\n   #212327 borders, no shadows, restrained sunset / dusk / breeze accents in\n   illustrations. Scoped under `.own-x-ai`. */\n\n.own-x-ai {\n  --xa-canvas: #0a0a0a;\n  --xa-canvas-soft: #1a1c20;\n  --xa-canvas-card: #191919;\n  --xa-hairline: #212327;\n  --xa-ink: #ffffff;\n  --xa-body: #dadbdf;\n  --xa-body-mid: #7d8187;\n  --xa-sunset: #ff7a17;\n  --xa-sunset-soft: #ffc285;\n  --xa-dusk: #7c3aed;\n  --xa-twilight: #c4b5fd;\n  --xa-breeze: #a0c3ec;\n  --xa-display: 'universalSans', 'Inter', system-ui, -apple-system, sans-serif;\n  --xa-mono: 'GeistMono', 'Geist Mono', ui-monospace, SFMono-Regular, Menlo, monospace;\n  --xa-gut: clamp(20px, 5cqi, 64px);\n\n  position: relative;\n  background: var(--xa-canvas);\n  color: var(--xa-ink);\n  font-family: var(--xa-display);\n  font-size: 16px;\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n  text-align: left;\n  border-radius: 13px;\n}\n\n.own-x-ai *, .own-x-ai *::before, .own-x-ai *::after { box-sizing: border-box; }\n.own-x-ai p { margin: 0; }\n.own-x-ai a { color: inherit; text-decoration: none; }\n.own-x-ai :focus-visible { outline: 2px solid var(--xa-ink); outline-offset: 3px; border-radius: 9999px; }\n.own-x-ai .xa-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }\n.own-x-ai .xa-eyebrow {\n  font-family: var(--xa-mono); font-size: 14px; font-weight: 400; letter-spacing: 1.4px;\n  text-transform: uppercase; color: var(--xa-body-mid); margin-bottom: 18px;\n}\n.own-x-ai .xa-hero-title {\n  font-size: clamp(44px, 8cqi, 96px); font-weight: 400; line-height: 1; letter-spacing: -.025em;\n  max-width: 16ch;\n}\n.own-x-ai .xa-sec-title {\n  font-size: clamp(32px, 5cqi, 72px); font-weight: 400; line-height: 1; letter-spacing: -.025em;\n  max-width: 18ch; margin-bottom: 40px;\n}\n\n/* ── pills (the entire shape system) ─────────────────────────────────────── */\n.own-x-ai .xa-pill {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  font-family: var(--xa-display); font-size: 14px; font-weight: 400;\n  padding: 12px 20px; border-radius: 9999px; border: 1px solid rgba(255,255,255,.25);\n  color: var(--xa-ink); background: transparent; cursor: pointer;\n  transition: background-color .18s ease, border-color .18s ease, color .18s ease;\n}\n.own-x-ai .xa-pill:hover { border-color: rgba(255,255,255,.55); background: rgba(255,255,255,.06); }\n.own-x-ai .xa-pill-sm { padding: 6px 14px; font-size: 14px; }\n.own-x-ai .xa-pill-fill { background: var(--xa-ink); color: var(--xa-canvas); border-color: var(--xa-ink); }\n.own-x-ai .xa-pill-fill:hover { background: #e6e6e6; border-color: #e6e6e6; }\n.own-x-ai .xa-pill-block { width: 100%; }\n\n/* ── nav ─────────────────────────────────────────────────────────────────── */\n.own-x-ai .xa-nav {\n  position: sticky; top: 68px; z-index: 30;\n  display: flex; align-items: center; gap: 32px; height: 64px; padding: 0 var(--xa-gut);\n  background: rgba(10,10,10,.86); backdrop-filter: blur(12px);\n  border-bottom: 1px solid var(--xa-hairline);\n}\n.own-x-ai .xa-brand { font-size: 16px; font-weight: 400; letter-spacing: .28em; white-space: nowrap; }\n.own-x-ai .xa-nav-links { display: flex; align-items: center; gap: 26px; }\n.own-x-ai .xa-nav-links a { font-size: 14px; color: var(--xa-body); transition: color .18s ease; }\n.own-x-ai .xa-nav-links a:hover { color: var(--xa-ink); }\n.own-x-ai .xa-nav-actions { margin-left: auto; display: flex; align-items: center; gap: 10px; }\n\n/* ── hero ────────────────────────────────────────────────────────────────── */\n.own-x-ai .xa-hero { padding: 104px var(--xa-gut) 72px; max-width: 1200px; margin: 0 auto; }\n.own-x-ai .xa-hero-lead {\n  font-size: clamp(16px, 1.8cqi, 18px); line-height: 1.55; color: var(--xa-body);\n  max-width: 52ch; margin-top: 26px;\n}\n.own-x-ai .xa-hero-cta { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 36px; }\n\n/* ── metrics ─────────────────────────────────────────────────────────────── */\n.own-x-ai .xa-metrics { border-top: 1px solid var(--xa-hairline); border-bottom: 1px solid var(--xa-hairline); }\n.own-x-ai .xa-metric-row {\n  display: grid; grid-template-columns: repeat(4, 1fr);\n  max-width: 1200px; margin: 0 auto; padding: 0 var(--xa-gut);\n}\n.own-x-ai .xa-metric {\n  display: flex; flex-direction: column; gap: 10px; padding: 40px 0;\n  border-right: 1px solid var(--xa-hairline);\n}\n.own-x-ai .xa-metric:last-child { border-right: 0; }\n.own-x-ai .xa-metric + .xa-metric { padding-left: 32px; }\n.own-x-ai .xa-metric-num { font-size: clamp(32px, 4cqi, 48px); font-weight: 400; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }\n.own-x-ai .xa-metric-cap { font-family: var(--xa-mono); font-size: 12px; letter-spacing: 1.2px; color: var(--xa-body-mid); }\n\n/* ── products ────────────────────────────────────────────────────────────── */\n.own-x-ai .xa-products { padding: 104px var(--xa-gut) 0; max-width: 1200px; margin: 0 auto; }\n.own-x-ai .xa-product-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }\n.own-x-ai .xa-card {\n  display: flex; flex-direction: column; gap: 14px; padding: 24px;\n  background: var(--xa-canvas-card); border: 1px solid var(--xa-hairline); border-radius: 8px;\n}\n.own-x-ai .xa-card-ico { display: inline-grid; place-items: center; width: 48px; height: 48px; margin-bottom: 6px; background: var(--xa-canvas-soft); border-radius: 8px; }\n.own-x-ai .xa-card-ico svg { width: 32px; height: 32px; fill: none; }\n.own-x-ai .xa-card-tag { font-family: var(--xa-mono); font-size: 12px; letter-spacing: 1.2px; color: var(--xa-body-mid); }\n.own-x-ai .xa-card-title { font-size: 24px; font-weight: 400; letter-spacing: -.015em; line-height: 1.15; }\n.own-x-ai .xa-card-body { font-size: 16px; line-height: 1.55; color: var(--xa-body); margin-bottom: 6px; }\n.own-x-ai .xa-card .xa-pill { align-self: flex-start; margin-top: auto; }\n\n/* ── console ─────────────────────────────────────────────────────────────── */\n.own-x-ai .xa-console { padding: 104px var(--xa-gut) 0; max-width: 1200px; margin: 0 auto; }\n.own-x-ai .xa-console-head { margin-bottom: 32px; }\n.own-x-ai .xa-console-head .xa-sec-title { margin-bottom: 0; }\n.own-x-ai .xa-term { border: 1px solid var(--xa-hairline); border-radius: 8px; overflow: hidden; background: var(--xa-canvas-card); }\n.own-x-ai .xa-term-bar {\n  display: flex; align-items: center; gap: 7px; height: 40px; padding: 0 16px;\n  background: var(--xa-canvas-soft); border-bottom: 1px solid var(--xa-hairline);\n}\n.own-x-ai .xa-term-dot { width: 10px; height: 10px; border-radius: 50%; background: #3a3d42; }\n.own-x-ai .xa-term-title { margin-left: 12px; font-family: var(--xa-mono); font-size: 12px; letter-spacing: .4px; color: var(--xa-body-mid); }\n.own-x-ai .xa-term-body {\n  margin: 0; padding: 24px; font-family: var(--xa-mono); font-size: 14px; line-height: 1.9;\n  letter-spacing: .2px; color: var(--xa-body); overflow-x: auto; white-space: pre;\n}\n.own-x-ai .xa-c-dim { color: #565a60; }\n.own-x-ai .xa-c-ok { color: #6fe08a; }\n.own-x-ai .xa-c-warn { color: var(--xa-sunset-soft); }\n.own-x-ai .xa-c-hot { color: var(--xa-ink); }\n.own-x-ai .xa-c-cursor { color: var(--xa-sunset); animation: xaBlink 1.1s step-end infinite; }\n@keyframes xaBlink { 50% { opacity: 0; } }\n\n/* ── pricing ─────────────────────────────────────────────────────────────── */\n.own-x-ai .xa-pricing { padding: 104px var(--xa-gut) 0; max-width: 1200px; margin: 0 auto; }\n.own-x-ai .xa-price-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; align-items: stretch; }\n.own-x-ai .xa-price-card {\n  display: flex; flex-direction: column; gap: 16px; padding: 24px;\n  background: var(--xa-canvas-soft); border: 1px solid var(--xa-hairline); border-radius: 8px;\n}\n.own-x-ai .xa-price-feat { background: var(--xa-canvas-card); }\n.own-x-ai .xa-price-card h3 { font-size: 24px; font-weight: 400; letter-spacing: -.015em; }\n.own-x-ai .xa-price { font-size: 14px; color: var(--xa-body-mid); }\n.own-x-ai .xa-price span { font-size: 40px; font-weight: 400; letter-spacing: -.02em; color: var(--xa-ink); }\n.own-x-ai .xa-feats { list-style: none; margin: 0 0 8px; padding: 0; display: flex; flex-direction: column; gap: 10px; }\n.own-x-ai .xa-feats li { position: relative; padding-left: 22px; font-size: 16px; color: var(--xa-body); }\n.own-x-ai .xa-feats li::before {\n  content: ''; position: absolute; left: 0; top: 7px; width: 8px; height: 8px; border-radius: 50%;\n  border: 1px solid var(--xa-body-mid);\n}\n.own-x-ai .xa-price-card .xa-pill { margin-top: auto; }\n\n/* ── CTA ─────────────────────────────────────────────────────────────────── */\n.own-x-ai .xa-cta { padding: 128px var(--xa-gut) 104px; max-width: 1200px; margin: 0 auto; }\n.own-x-ai .xa-cta-title { font-size: clamp(36px, 6cqi, 96px); font-weight: 400; line-height: 1; letter-spacing: -.025em; max-width: 14ch; margin-bottom: 36px; }\n\n/* ── footer ──────────────────────────────────────────────────────────────── */\n.own-x-ai .xa-footer { border-top: 1px solid var(--xa-hairline); padding: 64px var(--xa-gut) 40px; }\n.own-x-ai .xa-foot-grid { display: grid; grid-template-columns: 1.6fr repeat(3, 1fr); gap: 32px; max-width: 1200px; margin: 0 auto; }\n.own-x-ai .xa-foot-brand p { font-size: 14px; line-height: 1.6; color: var(--xa-body-mid); margin-top: 14px; max-width: 30ch; }\n.own-x-ai .xa-foot-col { display: flex; flex-direction: column; gap: 10px; }\n.own-x-ai .xa-foot-col h4 { font-family: var(--xa-mono); font-size: 12px; letter-spacing: 1.2px; font-weight: 400; color: var(--xa-body-mid); margin-bottom: 4px; }\n.own-x-ai .xa-foot-col a { font-size: 14px; color: var(--xa-body); }\n.own-x-ai .xa-foot-col a:hover { color: var(--xa-ink); }\n.own-x-ai .xa-foot-base {\n  display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap;\n  max-width: 1200px; margin: 48px auto 0; padding-top: 24px;\n  border-top: 1px solid var(--xa-hairline);\n  font-family: var(--xa-mono); font-size: 12px; letter-spacing: .4px; color: var(--xa-body-mid);\n}\n\n/* ── responsive — @container frame ───────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-x-ai .xa-hero { padding-top: 80px; }\n  .own-x-ai .xa-product-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-x-ai .xa-price-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-x-ai .xa-price-feat { grid-column: span 2; }\n  .own-x-ai .xa-foot-grid { grid-template-columns: 1fr 1fr; }\n  .own-x-ai .xa-foot-brand { grid-column: span 2; }\n}\n@container frame (max-width: 760px) {\n  .own-x-ai .xa-nav-links { display: none; }\n  .own-x-ai .xa-metric-row { grid-template-columns: repeat(2, 1fr); }\n  .own-x-ai .xa-metric { padding: 28px 0; }\n  .own-x-ai .xa-metric:nth-child(2) { border-right: 0; }\n  .own-x-ai .xa-metric + .xa-metric { padding-left: 24px; }\n  .own-x-ai .xa-metric:nth-child(3) { padding-left: 0; }\n  .own-x-ai .xa-product-grid { grid-template-columns: 1fr; }\n  .own-x-ai .xa-price-grid { grid-template-columns: 1fr; }\n  .own-x-ai .xa-price-feat { grid-column: span 1; }\n  .own-x-ai .xa-products, .own-x-ai .xa-console, .own-x-ai .xa-pricing { padding-top: 72px; }\n  .own-x-ai .xa-cta { padding-top: 80px; }\n}\n@container frame (max-width: 430px) {\n  .own-x-ai .xa-hero-cta { flex-direction: column; }\n  .own-x-ai .xa-hero-cta .xa-pill { width: 100%; }\n  .own-x-ai .xa-foot-grid { grid-template-columns: 1fr; }\n  .own-x-ai .xa-foot-brand { grid-column: span 1; }\n  .own-x-ai .xa-term-body { font-size: 12px; padding: 16px; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-x-ai .xa-pill { transition: none; }\n  .own-x-ai .xa-c-cursor { animation: none; }\n}\n"};
/* ══ X.AI — own layout behaviour for showcase.html ═════════════════════════
   Registers window.OWN_LAYOUTS['x.ai'].init(root). Counts the metric figures
   up on first reveal. init returns a cleanup that cancels rAF and disconnects
   observers. Query only inside `root`. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  OWN['x.ai'] = {
    init: function (root) {
      var reduced = false;
      try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { /* ignore */ }

      var rafs = [];
      var observers = [];

      function raf(fn) { var id = requestAnimationFrame(fn); rafs.push(id); return id; }
      function fmt(n) { return Math.round(n).toLocaleString('en-US'); }

      function countTo(el) {
        var target = Number(el.getAttribute('data-xa-count'));
        if (!isFinite(target)) return;
        var start = 0;
        function step(ts) {
          if (!start) start = ts;
          var p = Math.min(1, (ts - start) / 900);
          var eased = 1 - Math.pow(1 - p, 3);
          el.textContent = fmt(target * eased);
          if (p < 1) raf(step);
        }
        raf(step);
      }

      var nums = root.querySelectorAll('[data-xa-count]');
      if (reduced || typeof IntersectionObserver === 'undefined') {
        nums.forEach(function (el) { var t = Number(el.getAttribute('data-xa-count')); if (isFinite(t)) el.textContent = fmt(t); });
      } else {
        var io = new IntersectionObserver(function (entries) {
          entries.forEach(function (en) { if (en.isIntersecting) { countTo(en.target); io.unobserve(en.target); } });
        }, { threshold: .4 });
        nums.forEach(function (el) { io.observe(el); });
        observers.push(io);
      }

      return function cleanup() {
        rafs.forEach(function (id) { cancelAnimationFrame(id); });
        observers.forEach(function (o) { try { o.disconnect(); } catch (e) { /* ignore */ } });
      };
    }
  };
})();
